function validate([queries]) {
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 500) return 'queries needs 1 to 500 entries.';
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 3 || !query.every(Number.isInteger)) return 'Each query is three integers [from, to, mod].';
    const [from, to, mod] = query;
    if (from < 0 || from > to || to > 1e15) return 'Each query needs 0 <= from <= to <= 10^15.';
    if (mod < 1 || mod > 100000) return 'Each mod is between 1 and 10^5.';
  }
  return null;
}

