function findProductsOfElements(queries) {
  // Exact BigInt arithmetic, a binary search over numbers, and a split on each number's highest bit.
  // below(v) = [how many elements, sum of their exponents] in the powerful arrays of 0..v-1.
  // For v = 2^j + r: the numbers under 2^j give j * 2^(j-1) elements whose exponents add to 2^(j-1) * j(j-1)/2,
  // and each of 2^j..v-1 is 2^j plus a number under r.
  const below = (v) => {
    if (v === 0n) return [0n, 0n];
    const j = BigInt(v.toString(2).length - 1);
    const top = 1n << j;
    const [count, sum] = below(v - top);
    return [j * top / 2n + (v - top) + count, j * (j - 1n) / 2n * top / 2n + j * (v - top) + sum];
  };
  // Sum of the exponents of the first k elements of big_nums.
  const exponentPrefix = (k) => {
    let low = 1n, high = k + 1n;
    while (low < high) {
      const mid = (low + high + 1n) / 2n;
      if (below(mid)[0] <= k) low = mid;
      else high = mid - 1n;
    }
    let [count, sum] = below(low);
    // The prefix ends inside the powerful array of low: take its smallest powers.
    for (let j = 0n; count < k; j++) {
      if ((low >> j) & 1n) {
        sum += j;
        count++;
      }
    }
    return sum;
  };
  const powerOfTwo = (exponent, mod) => {
    let result = 1n % mod, base = 2n % mod;
    for (; exponent > 0n; exponent >>= 1n) {
      if (exponent & 1n) result = (result * base) % mod;
      base = (base * base) % mod;
    }
    return result;
  };
  return queries.map(([from, to, mod]) => Number(powerOfTwo(exponentPrefix(BigInt(to) + 1n) - exponentPrefix(BigInt(from)), BigInt(mod))));
}

